<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, apiError, type ExperimentAssignment } from '../api/client'
import { useRouter } from 'vue-router'
const router=useRouter();const assignments=ref<ExperimentAssignment[]>([]);const loading=ref(true);const error=ref('');const working=ref(false)
async function load(){try{assignments.value=(await api.get<ExperimentAssignment[]>('/experiment-tasks')).data}catch(cause){error.value=apiError(cause,'实验任务暂时无法加载。')}finally{loading.value=false}}
async function start(assignment:ExperimentAssignment){working.value=true;error.value='';try{const current=(await api.post<ExperimentAssignment>('/experiment-tasks/'+assignment.id+'/start')).data;await router.push({path:'/evaluation',query:{taskKey:current.title,conditionKey:current.conditionKey,taskOrder:'A→B',assignmentId:String(current.id),taskId:String(current.taskId)}})}catch(cause){error.value=apiError(cause,'实验任务启动失败。')}finally{working.value=false}}
function openQuestionnaire(task:ExperimentAssignment){void router.push({path:'/evaluation',query:{taskKey:task.title,conditionKey:task.conditionKey,taskOrder:'A→B',assignmentId:String(task.id),taskId:String(task.taskId)}})}
onMounted(load)
</script>
<template><div class="page-stack experiment-tasks-page"><header class="page-heading"><div><p class="eyebrow">SERVER-MANAGED EXPERIMENTS</p><h1>实验任务</h1><p>任务、分组、顺序和完成状态由服务器记录；先阅读知情说明，再开始前测和实验任务。</p></div></header><div v-if="error" class="inline-notice" role="alert">{{ error }}</div><section v-if="loading" class="empty-state">正在加载实验任务…</section><section v-else class="task-list"><article v-for="task in assignments" :key="task.id" class="task-card"><div class="task-card-heading"><div><strong>{{ task.title }}</strong><small>{{ task.groupName }} · {{ task.conditionKey }} · {{ task.experimentType }}</small></div><span :class="['status-tag',task.status.toLowerCase()]">{{ task.status === 'ASSIGNED' ? '待开始' : task.status === 'IN_PROGRESS' ? '进行中' : '已完成' }}</span></div><p>{{ task.description || '完成指定问答实验并提交真实服务器结果。' }}</p><div class="task-protocol"><span>顺序 A→B</span><span>前测 → 任务 → 后测</span><span>可补录延后测验</span></div><div class="task-question">{{ task.question }}</div><div class="task-actions"><button class="primary-button" :aria-label="'开始实验任务 ' + task.id" :disabled="working || task.status === 'COMPLETED' || task.taskStatus !== 'OPEN'" @click="start(task)">{{ task.status === 'COMPLETED' ? '已完成' : task.taskStatus !== 'OPEN' ? '等待开放' : '开始评估与任务' }}</button><button class="secondary-button" :disabled="working || task.status === 'COMPLETED'" @click="openQuestionnaire(task)">仅查看评估说明</button></div></article><div v-if="!assignments.length" class="empty-state">当前账户还没有被分配实验任务。</div></section></div></template>
<style scoped>.task-list{display:grid;gap:14px}.task-card{display:grid;gap:12px;padding:18px;background:var(--surface);border:1px solid var(--border-default);border-radius:var(--radius-md);box-shadow:var(--shadow-sm)}.task-card-heading{display:flex;justify-content:space-between;gap:12px}.task-card-heading strong,.task-card-heading small{display:block}.task-card-heading small{margin-top:5px;color:var(--text-muted);font-size:10px}.task-card p{margin:0;color:var(--text-muted);font-size:12px;line-height:1.6}.task-protocol{display:flex;flex-wrap:wrap;gap:7px}.task-protocol span{padding:5px 8px;color:var(--accent);background:var(--accent-soft);border-radius:var(--radius-sm);font-size:10px}.task-question{padding:10px 12px;color:var(--text);background:var(--surface-soft);border-left:3px solid var(--accent);font-size:12px}.status-tag{padding:4px 7px;border-radius:5px;font-size:10px}.status-tag.assigned{background:var(--warning-soft);color:var(--warning)}.status-tag.in_progress{background:var(--info-soft);color:var(--info)}.status-tag.completed{background:var(--accent-soft);color:var(--accent)}.task-actions{display:flex;flex-wrap:wrap;gap:8px}.primary-button,.secondary-button{min-height:34px;border-radius:var(--radius-sm);padding:0 14px;cursor:pointer}.primary-button{border:0;background:var(--accent);color:#fff}.secondary-button{border:1px solid var(--border-default);background:var(--surface);color:var(--text-muted)}button:disabled{opacity:.5;cursor:not-allowed}</style>
